type Role = "TRAVELLER" | "ADMIN";
type User = { id?: number; name: string; email: string; role: Role; phone?: string };
type Destination = { id: string; name: string; country: string; region: string; category: string; image: string; description: string; rating: number; startingAt: number };
type Stay = { id: string; name: string; destination: string; type: string; rating: number; price: number; location?: string; rooms?: number };
type Ride = { id: string; name: string; destination: string; mode: string; duration: string; price: number; origin?: string; destinationName?: string; availableSeats?: number };
type TripPackage = { id: string; name: string; destination: string; nights: number; inclusions: string[]; price: number; description?: string };
type Booking = { id: string; code: string; owner: string; destination: string; packageName: string; hotel?: string; transport?: string; start: string; end: string; guests: number; total: number; status: "PENDING_PAYMENT" | "CONFIRMED" | "CANCELLED"; paymentStatus: "UNPAID" | "SUCCEEDED" | "FAILED"; createdAt: string; inventoryCleanupRequired?: boolean };
const DESTINATIONS: Destination[] = [
  { id: "bali", name: "Bali", country: "Indonesia", region: "Southeast Asia", category: "Island", image: "/images/bali-terraces.jpg", description: "Follow the green ridgelines into a slower rhythm of temple courtyards, volcanic mornings and long afternoons by the water.", rating: 4.9, startingAt: 840 },
  { id: "kyoto", name: "Kyoto", country: "Japan", region: "East Asia", category: "Culture", image: "/images/kyoto-evening.jpg", description: "A city of lantern-lit lanes, quiet gardens and small rituals tucked between the mountains and the old town.", rating: 4.8, startingAt: 690 },
  { id: "alps", name: "Swiss Alps", country: "Switzerland", region: "Central Europe", category: "Nature", image: "/images/alpine-lake.jpg", description: "Clear lake mornings, high trails and mountain villages linked by some of the world’s most beautiful rail journeys.", rating: 4.9, startingAt: 1160 },
  { id: "kyoto-dusk", name: "Higashiyama", country: "Japan", region: "East Asia", category: "Culture", image: "/images/kyoto-dusk.jpg", description: "A gentle evening walk through wooden streets beneath the pagodas of Kyoto’s historic hills.", rating: 4.7, startingAt: 720 },
];
const PACKAGES: TripPackage[] = [
  { id: "bali-slow", name: "The slower side of Bali", destination: "bali", nights: 6, inclusions: ["Ubud rice terrace walk", "Temple visit with local guide", "Daily breakfast"], price: 420 },
  { id: "bali-coast", name: "Ubud to the coast", destination: "bali", nights: 8, inclusions: ["Ubud & Uluwatu stays", "Private airport transfer", "Sunset coastal walk"], price: 680 },
  { id: "kyoto-lanes", name: "Kyoto, one lane at a time", destination: "kyoto", nights: 5, inclusions: ["Higashiyama walking tour", "Tea room experience", "Rail pass"], price: 510 },
  { id: "alpine-rail", name: "The alpine rail week", destination: "alps", nights: 7, inclusions: ["Scenic rail pass", "Lakeside village guide", "Daily breakfast"], price: 860 },
];
